type RuntimeBackend = 'claude-cli' | 'codex-cli' | 'openhands-sdk' | 'gemini' | 'langchain';

interface ProviderPolicy {
  backupOrder?: RuntimeBackend[];
}

export class AgentExecutor {
  constructor() {}

  private resolveBackendFromContext(
    context: RunContext,
    primary: 'claude-cli' | 'codex-cli' | 'openhands-sdk',
  ): 'claude-cli' | 'codex-cli' | 'openhands-sdk' {
    if (context.executionTarget === 'claude-cli') return 'claude-cli';
    if (context.executionTarget === 'codex-cli') return 'codex-cli';
    if (context.executionTarget === 'openhands') return 'openhands-sdk';
    return primary;
  }

  private loadProviderPolicy(workspacePath: string): ProviderPolicy {
    const filePath = path.resolve(workspacePath || process.cwd(), 'docs/runtime/adaptive/provider-backup-policy.json');
    if (!fs.existsSync(filePath)) {
      return { backupOrder: ['codex-cli', 'claude-cli', 'openhands-sdk', 'gemini', 'langchain'] };
    }
    try {
      return JSON.parse(fs.readFileSync(filePath, 'utf-8')) as ProviderPolicy;
    } catch {
      return { backupOrder: ['codex-cli', 'claude-cli', 'openhands-sdk', 'gemini', 'langchain'] };
    }
  }

  private resolveExecutionChain(context: RunContext): RuntimeBackend[] {
    const cfg = loadConfig(context.workspacePath);
    const preferred = this.resolveBackendFromContext(context, cfg.backend);
    const policy = this.loadProviderPolicy(context.workspacePath || process.cwd());
    const chain = [preferred as RuntimeBackend, ...(policy.backupOrder || [])];
    return Array.from(new Set(chain));
  }

  private createAdapter(backend: RuntimeBackend): ExecutionAdapter | null {
    if (backend === 'claude-cli') return new ClaudeCliAdapter();
    if (backend === 'codex-cli') return new CodexCliAdapter();
    if (backend === 'openhands-sdk') return new OpenHandsAdapter();
    if (backend === 'gemini') {
      if (!process.env.GOOGLE_API_KEY) return null;
      return new GeminiAdapter(process.env.GOOGLE_API_KEY, process.env.GOOGLE_MODEL || 'gemini-1.5-flash');
    }
    if (backend === 'langchain') {
      if (!process.env.OPENAI_API_KEY) return null;
      return new LangChainAdapter(process.env.OPENAI_API_KEY);
    }
    return null;
  }

  private applyBackendContext(context: RunContext, backend: RuntimeBackend): void {
    const cfg = loadConfig(context.workspacePath);
    if (backend === 'claude-cli') {
      context.executionTarget = 'claude-cli';
      context.provider = 'claude-cli';
      context.model = cfg.claude.model;
    } else if (backend === 'codex-cli') {
      context.executionTarget = 'codex-cli';
      context.provider = 'codex-cli';
      context.model = cfg.codex.model;
    } else if (backend === 'openhands-sdk') {
      context.executionTarget = 'openhands';
      context.provider = 'openhands-sdk';
      context.model = cfg.openhands.model;
    } else if (backend === 'gemini') {
      context.executionTarget = 'direct';
      context.provider = 'google-gemini';
      context.model = process.env.GOOGLE_MODEL || 'gemini-1.5-flash';
    } else {
      context.executionTarget = 'direct';
      context.provider = 'openai';
      context.model = process.env.OPENAI_MODEL || 'gpt-4o';
    }
  }

  async run(context: RunContext, providedAdapter?: ExecutionAdapter): Promise<ExecutionResult> {
    const chain = providedAdapter ? [] : this.resolveExecutionChain(context);
    const failures: string[] = [];
    let result: ExecutionResult | null = null;
    let durationMs = 0;

    if (providedAdapter) {
      const startedAt = Date.now();
      const runner = new NativeToolLoopRunner(providedAdapter);
      result = await runner.run(context);
      durationMs = Date.now() - startedAt;
    } else {
      for (let i = 0; i < chain.length; i += 1) {
        const backend = chain[i];
        const adapter = this.createAdapter(backend);
        if (!adapter) {
          failures.push(`${backend}:adapter_unavailable`);
          continue;
        }
        this.applyBackendContext(context, backend);
        const startedAt = Date.now();
        const runner = new NativeToolLoopRunner(adapter);
        const attempt = await runner.run(context);
        durationMs = Date.now() - startedAt;
        if (attempt.ok) {
          result = attempt;
          if (i > 0) {
            logGovernance({
              rule: 'provider_backup_orchestration',
              status: 'pass',
              action: 'allow',
              ticket: context.activeTicketId,
              runId: context.runId,
              chainId: context.chainId,
              detail: `selected=${backend};attempt=${i + 1};failures=${failures.join('|') || 'none'}`,
            });
          }
          break;
        }
        failures.push(`${backend}:${attempt.error || 'failed'}`);
        logGovernance({
          rule: 'provider_backup_orchestration',
          status: 'fail',
          action: 'warn',
          ticket: context.activeTicketId,
          runId: context.runId,
          chainId: context.chainId,
          detail: `backend=${backend};attempt=${i + 1};error=${attempt.error || 'failed'}`,
        });
      }
    }

    if (result?.ok) {
      // Sprint A: Save Structured Artifact to Blackboard
      await BlackboardService.saveArtifact({ 
        projectId: context.projectId, 
        chainId: context.chainId, 
        runId: context.runId 
      }, {
        runId: context.runId,
        stageId: context.pipeline.currentStageId,
        roleSlug: context.agent.slug,
        timestamp: new Date().toISOString(),
        summary: result.content.slice(0, 1000), // Primary textual output
        findings: result.findings,
        decisions: result.decisions,
        // If the status is handoff, we normally set this in the result
        handoff: result.responseMode === 'handoff' ? {
          nextRole: 'unknown', // Will be refined by the router/graph
          rationale: 'Stage completed, transitioning.'
        } : undefined
      });

      // Sprint 5.5 — Governance Soft Gates
      const ticketId = context.activeTicketId || 'AGSYS-UNKNOWN';
      const { logParticipationGate } = await import('./governance/AgentParticipationEnforcer');
      logParticipationGate({
        agentSlug: context.agent.slug,
        ticketId,
        runId: context.runId,
        chainId: context.chainId,
        content: result.content
      });

      const { logCostTrackerGate } = await import('./governance/CostTrackerEnforcer');
      logCostTrackerGate({
        ticketId,
        runId: context.runId,
        chainId: context.chainId,
        agentSlug: context.agent.slug,
        inputTokens: result.usage?.inputTokens || 0,
        outputTokens: result.usage?.outputTokens || 0,
        totalTokens: result.usage?.totalTokens || 0,
      });

      // Telemetry
      await this.emitTelemetry(context, result, durationMs);
    } else {
      throw new Error(`Execution failed across backup chain: ${failures.join(' | ') || result?.error || 'unknown'}`);
    }

    return result;
  }

  private async emitTelemetry(context: RunContext, result: ExecutionResult, durationMs: number) {
    if (!context.agent.skills || context.agent.skills.length === 0) return;

    const inputTokens = result.usage?.inputTokens || 0;
    const outputTokens = result.usage?.outputTokens || 0;
    const totalTokens = result.usage?.totalTokens || 0;

    await Promise.all(
      context.agent.skills.map((skillId) => {
        const skill = SkillRegistry.getSkill(skillId);
        if (!skill) return Promise.resolve();

        return appendSkillUsage({
          timestamp: new Date().toISOString(),
          runId: context.runId,
          ticketId: context.activeTicketId || 'none',
          threadId: context.runId,
          roleSlug: context.agent.slug,
          pipelineId: context.pipeline.id,
          stage: context.pipeline.currentStageId,
          skillId,
          sourcePath: skill.sourcePath,
          durationMs,
          inputTokens,
          outputTokens,
          totalTokens,
          outcome: 'success',
        });
      }),
    );
  }
}

import { RunContext } from './context/RunContext';
import { ExecutionAdapter, ExecutionResult } from './adapters/ExecutionAdapter';
import { emitSwarmEvent } from './events/EventBus';
import { executeViaWorkbench } from './WorkbenchGateway';
import { evaluateMidExecutionQuota } from './billing/MidExecutionQuotaController';
import { shouldSmartRetry } from './optimization/SmartRetryPolicy';

export interface ToolResult {
  tool: string;
  status: 'success' | 'failed';
  content: any;
  summary: string;
  error?: string;
}

export interface ToolExecutionContext {
  runId: string;
  projectId: string;
  workspacePath: string;
}

export class NativeToolLoopRunner {
  private maxIterations = 15;

  constructor(private adapter: ExecutionAdapter) {}

  private summarizeToolContent(content: unknown, defaultValue: string): string {
    if (content === null || content === undefined) return defaultValue;
    if (typeof content === 'string') {
      const normalized = content.replace(/\s+/g, ' ').trim();
      if (!normalized) return defaultValue;
      return normalized.length > 260 ? `${normalized.slice(0, 259)}…` : normalized;
    }
    try {
      const json = JSON.stringify(content);
      if (!json) return defaultValue;
      return json.length > 260 ? `${json.slice(0, 259)}…` : json;
    } catch {
      return defaultValue;
    }
  }

  async run(context: RunContext): Promise<ExecutionResult> {
    let iteration = 0;
    let currentContext = { ...context };
    let lastResult: ExecutionResult | null = null;
    let consumedUsage = Number((context as any)?.billing?.currentUsage || 0);

    const { Guardrails } = await import('./guards/Guardrails');

    while (iteration < this.maxIterations) {
      iteration++;

      // 0. Update and check guardrails
      const { RunManager } = await import('./context/RunManager');
      RunManager.checkCancellation(context.runId);

      Guardrails.checkTimeLimit(context.runId);
      Guardrails.recordLLMCall(context.runId);

      const result = await this.adapter.execute(currentContext);
      lastResult = result;

      console.log(`[AUDIT] model_step_${iteration}_raw:`, JSON.stringify(result.content || ""));

      if (!result.ok) {
        const decision = shouldSmartRetry({
          workspacePath: context.workspacePath,
          errorText: String(result.error || result.content || ''),
          estimatedTokens: Number(result.usage?.totalTokens || 0),
        });
        if (!decision.retry) {
          return {
            ...result,
            error: `${String(result.error || 'execution_failed')};smart_retry_block:${decision.reason}`,
          };
        }
        try {
          const attempt = Guardrails.incrementRetry(context.runId, `step_${iteration}`);
          console.log(`[NativeToolLoop] Retrying step_${iteration}, attempt ${attempt}`);
          iteration--; // Backtrack one iteration to retry the same logical step
          continue;
        } catch (guardError: any) {
          return result; // Max retries exceeded, return the original failure
        }
      }

      const incrementUsage = Number(result.usage?.totalTokens || 0);
      const midQuota = evaluateMidExecutionQuota({
        quota: (context as any)?.billing?.quota,
        state: { consumedUsage },
        incrementUsage,
        burstAllowance: Number((context as any)?.billing?.burstAllowance || 0),
      });
      consumedUsage = midQuota.consumedUsage;
      if (!midQuota.continueExecution) {
        return {
          ok: false,
          content: result.content || '',
          error: `Execution safely terminated by mid-run quota enforcement: ${midQuota.reason}.`,
        };
      }

      // 1. Check if the model wants to call a tool
      if (result.responseMode === 'tool_call' && (result as any).toolCalls) {
        const toolCalls = (result as any).toolCalls;
        console.log(`[AUDIT] tool_call_raw:`, JSON.stringify(toolCalls));

        const toolResults: ToolResult[] = [];
        for (const call of toolCalls) {
          const toolResult = await this.executeTool(call.tool, call.args, context);
          console.log(`[AUDIT] tool_result_raw:`, JSON.stringify(toolResult.content));
          toolResults.push(toolResult);

          await emitSwarmEvent('tool.call', context, {
            tool: call.tool,
            status: toolResult.status,
            summary: toolResult.summary
          });
        }

        // 2. Inject results and loop back
        currentContext = this.injectToolResults(currentContext, result, toolResults);
        continue;
      }

      // 3. Terminal state reached (handoff, final, clarify) or no tools called
      return result;
    }

    return {
      ok: false,
      content: lastResult?.content || '',
      error: `Max iterations (${this.maxIterations}) exceeded for native tool loop.`
    };
  }

  private async executeTool(name: string, args: any, context: RunContext): Promise<ToolResult> {
    console.log(`[NativeToolLoop] Executing tool: ${name} with args:`, args);

    try {
      const toolResult = await executeViaWorkbench(name, args, context);
      if (toolResult.status === 'queued') {
        return {
          tool: name,
          status: 'failed',
          content: null,
          summary: toolResult.summary,
          error: 'tool_queued',
        };
      }
      if (toolResult.status === 'blocked') {
        return {
          tool: name,
          status: 'failed',
          content: null,
          summary: toolResult.summary,
          error: 'tool_blocked',
        };
      }
      if (toolResult.status === 'failed') {
        return {
          tool: name,
          status: 'failed',
          content: null,
          summary: toolResult.summary,
          error: toolResult.error || 'tool_failed',
        };
      }
      return {
        tool: name,
        status: 'success',
        content: toolResult.content,
        summary: this.summarizeToolContent(toolResult.content, `Successfully called ${name}`),
      };
    } catch (err: any) {
      return {
        tool: name,
        status: 'failed',
        content: null,
        summary: this.summarizeToolContent(err?.message || '', `Failed to call ${name}`),
        error: err.message
      };
    }
  }

  private injectToolResults(context: RunContext, assistantResult: ExecutionResult, results: ToolResult[]): RunContext {
    const newContext = { ...context };

    // 1. First, record the model's turn that initiated the tool calls
    newContext.memory.threadHistory.push({
      role: 'assistant',
      content: assistantResult.content,
      tool_calls: (assistantResult as any).toolCalls,
      rawParts: assistantResult.rawParts
    });

    // 2. Then record the observations
    results.forEach(res => {
      newContext.memory.threadHistory.push({
        role: 'observation',
        content: typeof res.content === 'string' ? res.content : JSON.stringify(res.content),
        tool_name: res.tool
      });
    });

    return newContext;
  }
}

import { RunContext, StructuredArtifact } from './context/RunContext';
import { getRedisClient } from './redisClient';

/**
 * BlackboardService provides a structured, hierarchical memory store
 * backed by Redis (simulated for now, or using Redis MCP).
 * 
 * It allows agents to:
 * 1. Publish Shared Facts (long-term knowledge for the current run).
 * 2. Log Decisions (rationale for specific actions).
 * 3. Reference Artifacts (links to generated files/outputs).
 */
export class BlackboardService {
  private static redisPrefix = 'agsys:';

  /**
   * Generates a hierarchical Redis key based on the Memory Contract Spec.
   * Format: agsys:{tenantId}:{workspaceId}:{projectId}:{environmentId}:{chainId}:{runId}:{entity}
   */
  private static getKey(
    context: {
      tenantId?: string;
      workspaceId?: string;
      projectId: string;
      environmentId?: string;
      chainId: string;
      runId: string;
    },
    entity: string,
  ): string {
    const tenantId = String(context.tenantId || process.env.DEFAULT_TENANT_ID || `tenant:${context.projectId}`).trim();
    const workspaceId = String(context.workspaceId || process.env.DEFAULT_WORKSPACE_ID || `workspace:${context.projectId}`).trim();
    const environmentId = String(context.environmentId || `env:${tenantId}:${workspaceId}:project:${context.projectId}`).trim();
    return `${this.redisPrefix}${tenantId}:${workspaceId}:${context.projectId}:${environmentId}:${context.chainId}:${context.runId}:${entity}`;
  }

  /**
   * Hydrates the memory section of the RunContext from the blackboard.
   */
  static async hydrate(context: RunContext): Promise<void> {
    const redis = getRedisClient();
    const { projectId, chainId, runId } = context;

    try {
      // 1. Fetch Artifacts (List)
      const artifactJsonList = await redis.lrange(this.getKey(context, 'artifacts'), 0, -1);
      context.artifacts.priorOutputs = artifactJsonList.map(s => JSON.parse(s));

      // 2. Fetch Facts (Hash) - Run Level
      const runFacts = await redis.hgetall(this.getKey(context, 'facts:run'));

      // 3. Fetch Facts (Hash) - Chain Level (Hydration rule: Chain facts take precedence over Run facts if keys collide, or they are merged)
      const chainFacts = await redis.hgetall(
        this.getKey({
          tenantId: context.tenantId,
          workspaceId: context.workspaceId,
          projectId,
          environmentId: (context as any).environmentId,
          chainId,
          runId: 'shared',
        }, 'facts:chain'),
      );

      // 4. Fetch Facts (Hash) - Project Level
      const projectFacts = await redis.hgetall(
        this.getKey({
          tenantId: context.tenantId,
          workspaceId: context.workspaceId,
          projectId,
          environmentId: (context as any).environmentId,
          chainId: 'shared',
          runId: 'shared',
        }, 'facts:project'),
      );

      context.memory.sharedFacts = {
        ...Object.fromEntries(Object.entries(projectFacts).map(([k, v]) => [k, JSON.parse(v)])),
        ...Object.fromEntries(Object.entries(chainFacts).map(([k, v]) => [k, JSON.parse(v)])),
        ...Object.fromEntries(Object.entries(runFacts).map(([k, v]) => [k, JSON.parse(v)]))
      };

      // 5. Fetch Decisions (Hash)
      const decisions = await redis.hgetall(this.getKey(context, 'decisions'));
      context.memory.runDecisions = Object.fromEntries(
        Object.entries(decisions).map(([k, v]) => [k, JSON.parse(v)])
      );

      // 6. Fetch Handoff Context
      const handoffJson = await redis.get(this.getKey(context, 'handoff'));
      if (handoffJson) {
        context.memory.handoffContext = JSON.parse(handoffJson);
      }

      console.log(`[BlackboardService] Hydrated memory for ${projectId}/${chainId}/${runId}`);
    } catch (err) {
      console.error(`[BlackboardService] Failed to hydrate ${runId}:`, err);
    }
  }

  /**
   * Saves a structured artifact to the blackboard.
   */
  static async saveArtifact(
    context: {
      tenantId?: string;
      workspaceId?: string;
      projectId: string;
      environmentId?: string;
      chainId: string;
      runId: string;
    },
    artifact: StructuredArtifact,
  ): Promise<void> {
    const redis = getRedisClient();
    await redis.rpush(this.getKey(context, 'artifacts'), JSON.stringify(artifact));
    console.log(`[BlackboardService] Saved artifact for run ${context.runId}`);
  }

  /**
   * Returns all stored artifacts for the given run context.
   */
  static async getArtifacts(
    context: {
      tenantId?: string;
      workspaceId?: string;
      projectId: string;
      environmentId?: string;
      chainId: string;
      runId: string;
    },
  ): Promise<StructuredArtifact[]> {
    const redis = getRedisClient();
    const rows = await redis.lrange(this.getKey(context, 'artifacts'), 0, -1);
    return rows
      .map((row) => {
        try {
          return JSON.parse(row) as StructuredArtifact;
        } catch {
          return null;
        }
      })
      .filter((row): row is StructuredArtifact => row !== null);
  }

  /**
   * Publishes a fact to the shared blackboard at a specific level.
   */
  static async publishFact(
    context: {
      tenantId?: string;
      workspaceId?: string;
      projectId: string;
      environmentId?: string;
      chainId: string;
      runId: string;
    },
    key: string, 
    value: any, 
    level: 'run' | 'chain' | 'project' = 'run'
  ): Promise<void> {
    const redis = getRedisClient();
    let effectiveContext = { ...context };

    if (level === 'project') {
      effectiveContext = { ...effectiveContext, chainId: 'shared', runId: 'shared' };
    } else if (level === 'chain') {
      effectiveContext = { ...effectiveContext, runId: 'shared' };
    }

    const redisKey = this.getKey(effectiveContext, `facts:${level}`);
    await redis.hset(redisKey, key, JSON.stringify(value));
    console.log(`[BlackboardService] Published ${level} fact: ${key}`);
  }

  /**
   * Logs a decision to the blackboard.
   */
  static async logDecision(
    context: {
      tenantId?: string;
      workspaceId?: string;
      projectId: string;
      environmentId?: string;
      chainId: string;
      runId: string;
    },
    nodeName: string,
    decision: any,
  ): Promise<void> {
    const redis = getRedisClient();
    await redis.hset(this.getKey(context, 'decisions'), nodeName, JSON.stringify(decision));
  }

  /**
   * Sets the handoff context.
   */
  static async setHandoffContext(
    context: {
      tenantId?: string;
      workspaceId?: string;
      projectId: string;
      environmentId?: string;
      chainId: string;
      runId: string;
    },
    handoff: { fromRole: string; toRole: string; summary: string; rationale: string },
  ): Promise<void> {
    const redis = getRedisClient();
    await redis.set(this.getKey(context, 'handoff'), JSON.stringify(handoff));
  }
}
